    admitted = canonicalizeJson(record, JSON_RESOURCE_ENVELOPE);
  } catch (error) {
    if (["source-limit", "canonical-limit", "depth-limit", "node-limit", "object-member-limit",
      "array-length-limit", "string-limit", "key-limit"].includes(error?.code)) {
      throw unavailable("resource-limit", "unique-record-envelope", error);
    }
    throw new TypeError("unique record is not admissible JSON");
  }
  const commandValue = admitted.value?.witness?.observation?.payload?.[2];
  let addressed;
  let parsed;
  try {
    addressed = addressUniqueJournalCommand(commandValue, operation.configuration.journal);
    parsed = parseUniqueJournalRecord(admitted.value, operation.configuration.journal, addressed.slotDigest);
  } catch (error) {
    throw new TypeError("unique record does not satisfy the configured journal laws", { cause: error });
  }
  if (parsed.commandRef !== undefined) {
    throw new TypeError("unique parser returned an unsupported record shape");
  }
  const canonicalText = canonicalJson(parsed.record, JSON_RESOURCE_ENVELOPE);
  if (canonicalText !== admitted.text) {
    throw new TypeError("unique record is not its exact canonical representation");
  }
  const content = Buffer.from(`${canonicalText}\n`, "utf8");
  if (content.length > JSON_RESOURCE_ENVELOPE.maxSourceBytes + 1) {
    throw unavailable("resource-limit", "unique-record-envelope");
  }
  if (content.length > limits.maxBatchBytes) {
    throw unavailable("resource-limit", "source-batch-bytes");
  }
  const digest = parsed.slotDigest;
  const relativeName = `unique-admissions/v1/${digest}.json`;
  const sourceName = `${digest}.json`;
  const candidate = Object.freeze({
    name: relativeName, kind: "unique", identity: Object.freeze({ dev: 0, ino: 0 }),
    size: content.length, digest: createHash("sha256").update(content).digest("hex"), bytes: content,
  });
  let verifiedCandidate;
  try {
    verifiedCandidate = parseUniqueSource(candidate, operation.configuration);
  } catch (error) {
    if (isJournalUnavailable(error) && error.reason === "resource-limit") throw error;
    throw new TypeError("unique record does not satisfy the unique source laws", { cause: error });
  }
  if (verifiedCandidate.slotDigest !== digest
    || canonicalJson(verifiedCandidate.record, JSON_RESOURCE_ENVELOPE) !== canonicalText) {
    throw new TypeError("unique record does not correspond to its addressed slot");
  }

